// Builds two view-offset vectors from a stored position and the camera angle, tests them against the level, and
// possibly realigns the aim vector.
void adjust_hero_velocity_from_collision_probes(int arg) {
    struct Hero *p = (struct Hero *)g_hero;
    Vec4f a0;
    Vec4f u;
    Vec4f a1;
    Vec4f w;
    float sa;
    float sb;
    char *r;
    int s;
    float f;
    if (p->unk308 != 0)
        return;
    if (gravity_length_xy((float *)&p->motion.velocity) < g_frame_time * 0.1f)
        return;
    sa = 0.37f;
    sb = 0.5f;
    if ((unsigned)(p->state.control_mode - 0x11) < 2) {
        sa = 0.0f;
        sb = 0.7f;
    } else if (p->vehicle_mode == 1) {
        sa = 0.35f;
        sb = 0.27f;
    }
    r = &((struct Hero *)g_hero)->motion.pos;
    qcopy(&a0, r);
    a0.z = a0.z + sa;
    qcopy(&a1, r);
    a1.z = a1.z + sa * 0.3f;
    if (arg != 0 || vec_length_xy(r + 0x60) < 0.01f) {
        G98 *gg = (G98 *)(r - 0x80);
        u.x = FastCos(gg->ang) * sb;
        u.y = FastSin(gg->ang) * sb;
        u.z = 0.0f;
        w.x = FastCos(gg->ang) * sb * 1.4f;
        w.y = FastSin(gg->ang) * sb * 1.4f;
        w.z = 0.0f;
    } else {
        qcopy(&u, r + 0x60);
        u.z = 0.0f;
        FastVecScale(&u, &u, sb / vec_length_xy(&u));
        qcopy(&w, &u);
        FastVecScale(&w, &w, 1.4f);
    }
    FastVecAdd(&u, &u, &a0);
    s = -1;
    FastVecAdd(&w, &w, &a1);
    {
        struct Hero *g1 = (struct Hero *)g_hero;
        if (coll_line(&a1, &w, 4, *(int *)&g1->moby, 0) != 0 && blarg_coll_hit_type > 0) {
            s = CollType();
        }
    }
    f = 0.0f;
    {
        struct Hero *g2 = (struct Hero *)g_hero;
        if (coll_line(&a0, &u, 4, *(int *)&g2->moby, 0) != 0) {
            char *q = blarg_coll_hit;
            if (*(int *)(q + 0x1C) > 0) {
                f = fast_atan2(*(float *)(q + 0x48), vec_length_xy(q + 0x40));
            }
        }
    }
    if (f >= 0.87266463f || s == 8 || s == 12) {
        struct Hero *g = (struct Hero *)g_hero;
        char *q = blarg_coll_hit;
        float d;
        g->unk240 = *(int *)(q + 0x18);
        *(int *)(q + 0x48) = 0;
        sceVu0Normalize(q + 0x40, q + 0x40);
        d = -g->motion.velocity.f[0] * *(float *)(q + 0x40) - g->motion.velocity.f[1] * *(float *)(q + 0x44);
        if (d > 0.0f) {
            FastVecScale(q + 0x40, q + 0x40, d);
            FastVecAdd(&g->motion.velocity, &g->motion.velocity, q + 0x40);
        }
    }
}
